struct PtrState {
    SmallVector<StateInfo> stateInfo;  // shape info when load, maintained with visitOps
    SmallVector<OpFoldResult> sizes;    // original shape, maintained with visitOps
    SmallVector<size_t> permuteIds;
    SmallVector<size_t> order;   // the order of the original data format, only used for block_ptr
    SmallVector<OpFoldResult> dimOffsets; // the offsets per dimension, only used for block_ptr

    Value source;                // base address (ptr), maintained with visitOps
    OpFoldResult offset;        // scalar offset (int), maintained with visitOps

    // whether the record needs to be processed in the current pass, when ignore is true,
    // it indicates that this scenario should not be processed within the current pass
    bool shouldLinearize = false;
    bool isPermuted = false;

    void dump() const;
    bool isEmpty() const;
    bool isScalar() const;
    bool hasSource() const;
    bool isBlockPtr() const;
    bool isSameSizeAs(const PtrState& x) const;

    void generateOriginPermuteIds();

    // Formula of "contiguous axes"
    // - axis i is contiguous if stride[i] == product(shape[0..i-1]).
    size_t countContiguousAxes(SmallVector<StateInfo> stateInfo) const;
    void analyzePermute();

    void updatePtrState(SmallVector<StateInfo> stateInfo, SmallVector<OpFoldResult> sizes,
                        Value source, OpFoldResult offset, const Location loc,
                        OpBuilder& builder, bool shouldLinearize = false);

    void normalizeState(const Location loc, OpBuilder& builder);

    LogicalResult mulState(const PtrState& lhsState, const PtrState& rhsState,
                          Operation* op, OpBuilder& builder);

    LogicalResult subState(const PtrState& lhsState, const PtrState& rhsState,
                          Operation* op, OpBuilder& builder);

    LogicalResult addState(PtrState& lhsState, PtrState& rhsState, Operation* op,
                          OpBuilder& builder);

    triton::AddPtrOp createAddPtrOp(OpBuilder& builder, Location loc);

    triton::MakeTensorPtrOp createMakeTensorPtrOp(OpBuilder& builder, Location loc);
};

LogicalResult PtrAnalysis::visitOperand(Value operand, PtrState &state,
                                        const Location loc,
                                        OpBuilder &builder) {
    if (knownPtrs.find(operand) != knownPtrs.end()) {
        state = knownPtrs.lookup(operand);
        return success();
    }

    if (operandIsScalar(operand)) {
        return initStateByScalar(operand, state, loc, builder);
    }

    if (isa<triton::PointerType>(operand.getType())) {
        return initStateByPointer(operand, state, loc, builder);
    }

    if (auto op = operand.getDefiningOp<arith::AddIOp>()) {
        return visitOperandAdd(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<arith::MulIOp>()) {
        return visitOperandMul(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<arith::SubIOp>()) {
        return visitOperandSub(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<triton::MakeRangeOp>()) {
        return visitOperandMakeRange(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<triton::BroadcastOp>()) {
        return visitOperandBroadcast(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<triton::SplatOp>()) {
        return visitOperandSplat(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<triton::ExpandDimsOp>()) {
        return visitOperandExpandDims(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<triton::AddPtrOp>()) {
        return visitOperandAddptr(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<arith::ConstantOp>()) {
        return visitOperandConstSplat(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<arith::RemSIOp>()) {
        return visitOperandRem(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<arith::DivSIOp>()) {
        return visitOperandDiv(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<arith::ExtSIOp>()) {
        return visitOperandExtSI(op, state, loc, builder);
    } else if (auto op = operand.getDefiningOp<triton::LoadOp>()) {
        LLVM_DEBUG({
            op.emitRemark("TritonToStructured: Invalid dynamic offset"
                        "The load operation's offset cannot be derived from another load result.");
        });
        return failure();
    } else if (auto op = operand.getDefiningOp<arith::FPToSIOp>()) {
        LLVM_DEBUG({
            op.emitWarning("IllegalTypeConversionInAddressCalculation"
                        "float-to-int precision conversion is not supported during address computation.");
            llvm::dbgs() << "Operand: \n";
            operand.dump();
            llvm::dbgs() << "----------------------------------------------\n";
        });
        return failure();
    } else if (!operand.getDefiningOp()) {
        if (!knownPtrs.contains(operand)) {
            LLVM_DEBUG({
                llvm::dbgs() << "TritonToStructured: Pointer analysis is not supported for input parameters\n";
            });
            return failure();
        }

        // This operand must be an iter-arg of an inner-loop in a multiple-level
        // nested loop, which means its PtrState must have already been populated
        // during rewriteForOp of the parent loop.
        state = knownPtrs[operand];
        return success();
    } else {
        auto op = operand.getDefiningOp();
        LLVM_DEBUG({
            op->emitWarning("TritonToStructured: encountered addptr operand produced by an unsupported operation");
            llvm::dbgs() << "Operand: \n";
            operand.dump();
            llvm::dbgs() << "----------------------------------------------\n";
        });
        return failure();
    }
    return success();
}

LogicalResult PtrAnalysis::visitOperandMakeRange(triton::MakeRangeOp rangeOp,
                                                 PtrState &state, Location loc,
                                                 OpBuilder &builder) {
    if (!state.isEmpty()) {
        LLVM_DEBUG({
            rangeOp.emitError("PtrAnalysis: PtrState should be empty when visiting make_range");
        });
        return failure();
    }

    auto shape = cast<ShapedType>(rangeOp.getType()).getShape();

    auto start = rangeOp.getStart();
    auto end = rangeOp.getEnd();
    auto stride = (end - start + shape[0] - 1) / shape[0];
    if (stride != 1) {
        LLVM_DEBUG({
            rangeOp.emitError("PtrAnalysis: make_range op with stride != 1 is not supported");
        });
        return failure();
    }

    auto infoStride = builder.getIndexAttr(stride);
    auto size = builder.getIndexAttr(shape[0]);
    auto offset = builder.getIndexAttr(start);

    SmallVector<StateInfo> stateInfo;
    SmallVector<OpFoldResult> sizes;
    stateInfo.emplace_back(infoStride, size);
    sizes.emplace_back(size);

    state.updatePtrState(stateInfo, sizes, nullptr, offset, loc, builder);
    return success();
}

LogicalResult PtrState::addState(PtrState &lhsState,
                                 PtrState &rhsState, Operation *op,
                                 OpBuilder &builder) {
    auto loc = op->getLoc();

    if (!isEmpty()) {
        LLVM_DEBUG({
            op->emitError("PtrAnalysis: PtrState should be empty when adding");
        });
        return failure();
    }
    if (!lhsState.isSameSizeAs(rhsState)) {
        LLVM_DEBUG({
            op->emitError("PtrAnalysis: The original size of the addition should be the same");
        });
        return failure();
    }

    SmallVector<StateInfo> newStateInfo;
    auto lIt = lhsState.stateInfo.begin();
    auto rIt = rhsState.stateInfo.begin();
    while (lIt != lhsState.stateInfo.end() && rIt != rhsState.stateInfo.end()) {
        if (lIt->dimIndex != rIt->dimIndex) {
            auto newInfo = lIt->dimIndex < rIt->dimIndex ? *lIt++ : *rIt++;
            newStateInfo.emplace_back(newInfo);
            continue;
        }
        if (!isMultiple(lIt->shape, rIt->shape) &&
            !isMultiple(rIt->shape, lIt->shape)) {
            return failure();
        }

        auto newShape = minOpFoldResult(lIt->shape, rIt->shape, loc, builder);
        if ((isLess(newShape, lIt->shape) && !isZero(lIt->stride) ||
            isLess(newShape, rIt->shape) && !isZero(rIt->stride))) {
            return failure();
        }

        auto newStride = addOpFoldResult(lIt->stride, rIt->stride, loc, builder);
        newStateInfo.emplace_back(newStride, newShape, lIt->dimIndex);

        if (isEqual(lIt->shape, newShape))  ++lIt;
        else    lIt->shape = divOpFoldResult(lIt->shape, newShape, loc, builder);
        if (isEqual(rIt->shape, newShape))  ++rIt;
        else    rIt->shape = divOpFoldResult(rIt->shape, newShape, loc, builder);
    }

    while (rIt != rhsState.stateInfo.end()) {
        newStateInfo.push_back(*rIt++);
    }
    while (lIt != lhsState.stateInfo.end()) {
        newStateInfo.push_back(*lIt++);
    }

    auto newSource = source = lhsState.source ? lhsState.source : rhsState.source;
    auto newOffset = addOpFoldResult(lhsState.offset, rhsState.offset, loc, builder);
    auto newShouldLinearize = lhsState.shouldLinearize || rhsState.shouldLinearize;
    auto newSizes = lhsState.sizes;

    updatePtrState(newStateInfo, newSizes, newSource,
        newOffset, loc, builder, newShouldLinearize);

    return success();
}

void BlockDataParser::rewriteAddPtr(
    triton::AddPtrOp op, triton::AddPtrOp::Adaptor &adaptor,
    ConversionPatternRewriter &rewriter,
    llvm::SmallDenseMap<Value, BlockData> &known) {
  auto insertPoint = rewriter.saveInsertionPoint();
  rewriter.setInsertionPoint(op);

  BlockData data;
  parseAddPtr(op, data, op.getLoc(), rewriter, known);

  if (auto src = data.getSource();
      data.getMemAccTypeRef().isUnstructured() &&
      !(src && isa_and_nonnull<triton::IntToPtrOp>(src.getDefiningOp()))) {
    // TODO: Based on more info, try to create a performant IR
    rewriteAddPtrToUnstrucMemAcc(op, adaptor, rewriter, data);
    return;
  }

  if (data.getSizesRef().size() == 0) {
    data.getSizesRef().push_back(rewriter.getIndexAttr(1));
    data.getStridesRef().push_back(rewriter.getIndexAttr(0));
    data.getOffsetsRef().push_back(data.getScalarRef());
  }

  ArrayRef<int64_t> resultShape;
  // shape {1,} is stub for single ptr
  SmallVector<int64_t> stubScalarTypeShape(1, 1);
  if (auto shapedType = dyn_cast<ShapedType>(op.getResult().getType())) {
    resultShape = shapedType.getShape();
  } else {
    assert(data.getRank() == 1);
    resultShape = stubScalarTypeShape;
  }

  known[op.getResult()] = data;

  auto inferedSize = 1;
  auto hoistDim = op->getAttrOfType<IntegerAttr>("hoist_dim");
  for (int i = data.getSizesRef().size() - 1; i >= 0; i--) {
    auto strideConst = getConstantIntValue(data.getStridesRef()[i]);
    auto sizeConst = getConstantIntValue(data.getSizesRef()[i]);
    assert(sizeConst.has_value());
    bool shouldReplaceStride = (sizeConst.value() == 1) || (hoistDim && hoistDim.getValue() == i);
    if (shouldReplaceStride && strideConst && strideConst.value() == 0) {
      data.getStridesRef()[i] = rewriter.getIndexAttr(inferedSize);
    }
    inferedSize *= sizeConst.value();
  }

  memref::ReinterpretCastOp castOp =
      data.createCastOp(resultShape, op.getLoc(), rewriter);
  Value src = castOp.getResult();

  rewriter.replaceOp(op, src);
  rewriter.restoreInsertionPoint(insertPoint);
}

memref::ReinterpretCastOp BlockData::createCastOp(ArrayRef<int64_t> resultShape,
                                                  const Location &loc,
                                                  OpBuilder &builder) const {
  OpFoldResult resOffset = this->inferBlockOffset(loc, builder);
  auto resultType = this->getResultMemrefType(
      isa<Attribute>(resOffset) ? getConstantIntValue(resOffset).value()
                                : ShapedType::kDynamic,
      resultShape);

  SmallVector<OpFoldResult> strides(this->strides);
  for (size_t i = 0; i < strides.size(); i++) {
    if (resultShape[i] == 1) {
      if (auto strideValue = dyn_cast<Value>(strides[i])) {
        auto oneIdx = builder.create<arith::ConstantOp>(loc, builder.getIndexAttr(1));
        strides[i] = builder.create<arith::MaxSIOp>(loc, strideValue, oneIdx).getResult();
      }
    }
  }

  return builder.create<memref::ReinterpretCastOp>(
      loc, resultType, this->source, resOffset, this->sizes, strides);
}

